            s = s.decode()
        except Exception:
            # fallback: treat each byte as a separate character string
            s = ''.join(chr(b) for b in s)
    elif not isinstance(s, str):
        # If it's not a string, convert to string representation
        s = str(s)
    result = []
    if not s:
        return result
    cur = s[0]
    count = 1
    for ch in s[1:]:
