def solve(a, b):
    # Levenshtein distance using DP with O(min(m,n)) space
    if a is None or b is None:
        # treat None as empty string
        a = '' if a is None else a
        b = '' if b is None else b
    m, n = len(a), len(b)
    # ensure n is the smaller for space efficiency
    if n > m:
        a, b = b, a
        m, n = n, m
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j - 1], dp[j])
