def solve(matrix):
    """Return the elements of the 2D list *matrix* in clockwise spiral order.
    Handles empty matrices and non‑rectangular input gracefully by using the
    actual row lengths.
    """
    if not matrix or not any(matrix):
        return []
    # Determine boundaries
    top, bottom = 0, len(matrix) - 1
    left, right = 0, max(len(row) for row in matrix) - 1
    res = []
    while top <= bottom and left <= right:
        # top row
        for col in range(left, right + 1):
            if col < len(matrix[top]):
                res.append(matrix[top][col])
        top += 1
        # right column
        for row in range(top, bottom + 1):
            if right < len(matrix[row]):
                res.append(matrix[row][right])
        right -= 1
        if top > bottom:
            break
        # bottom row
        for col in range(right, left - 1, -1):
            if col < len(matrix[bottom]):
                res.append(matrix[bottom][col])
        bottom -= 1
        if left > right:
            break
        # left column
        for row in range(bottom, top - 1, -1):
            if left < len(matrix[row]):
                res.append(matrix[row][left])
        left += 1
    return res

